LESSONS=(
make_lesson(296,"Lesson_296-ingestion-architecture-the-six-step-harvest","Ingestion architecture - the six-step harvest","wiki.metadata.ingestion-six-step-harvest","Sáu bước metadata harvest tách discovery, extraction, normalization, enrichment, emission và reconciliation ra sao?",(DM,OL),(DML,OLL),a(
"Discover|Probe scope, permissions, versions, object counts và allow/deny rules trước crawl để biết expected population.","Extract|Đọc native APIs/logs/config/artifacts với cursors và rate limits; giữ raw work units hoặc snapshot để debug.","Normalize|Map native objects vào canonical identity/types mà không xóa source-specific fields hay uncertainty.","Enrich|Thêm ownership, domains, tags hoặc inferred relations bằng transformer có provenance riêng.","Emit|Validate schema, batch/idempotency identity và write result tới sink; partial success không được báo toàn run thành công.","Reconcile|So expected/seen/emitted/rejected/deleted counts, quarantine errors và chỉ advance checkpoint khi policy cho phép.")),
make_lesson(297,"Lesson_297-connector-concerns-incremental-crawl-partial-failure-preserved-annotations","Connector concerns - incremental crawl, partial failure, preserved annotations","wiki.metadata.connector-incremental-partial-annotations","Connector incremental phải xử lý checkpoint, partial failure và preserved annotations thế nào để không mất metadata do người dùng quản trị?",(DM,DL),(DML,DLL),a(
"Checkpoint semantics|Cursor có thể là timestamp, page token, log offset hay object version; checkpoint chỉ advance sau durable accepted scope.","Overlap and dedup|Incremental window thường cần overlap để chống late updates; canonical event/entity identity hấp thụ replay.","Partial failure|Phân loại permission, parse, rate limit, object-not-found và sink rejection; giữ failed work units để retry có scope.","Deletion detection|Full inventory diff, tombstone stream hay inactivity timeout có confidence khác nhau; không biến không thấy thành deleted ngay.","Preserved annotations|Connector-owned aspects được refresh; human/governance-owned aspects cần merge policy và không bị full snapshot ghi đè.","Connector SLO|Đo coverage, lag, error rate, checkpoint age và annotation-loss incidents thay vì chỉ job success.")),
make_lesson(298,"Lesson_298-lineage-levels-and-what-each-answers","Lineage levels and what each answers","wiki.metadata.lineage-levels","Entity, dataset, job, run và field lineage trả lời những câu hỏi khác nhau nào và không được suy vượt cấp ra sao?",(OL,OF,DL),(OLL,OFL,DLL),a(
"System/entity level|Cho biết platform hoặc asset lớn liên quan, hữu ích discovery nhưng quá thô cho impact kỹ thuật.","Dataset level|Nối input/output datasets, trả lời upstream/downstream và blast radius sơ bộ; chưa nói cột hay row nào ảnh hưởng.","Job level|Đặt transformation/process giữa datasets, hỗ trợ ownership và operational diagnosis.","Run level|Gắn dependency với execution, code/version, nominal time và actual inputs; cần cho incident/reproducibility.","Field level|Direct/indirect transformation của columns tăng precision nhưng parser, dynamic SQL và UDF tạo unknowns.","Question-fit rule|Chọn mức nhỏ nhất đủ trả lời câu hỏi; graph sâu hơn không tự chính xác hơn nếu provenance/confidence yếu.")),
make_lesson(299,"Lesson_299-five-extraction-methods-and-their-weaknesses","Five extraction methods and their weaknesses","wiki.metadata.lineage-extraction-methods","Năm phương pháp extraction lineage có coverage, freshness và failure modes khác nhau thế nào?",(OL,OF,DL),(OLL,OFL,DLL),a(
"Declared configuration|DAG/dbt/config graph cho intended dependencies nhưng có thể bỏ dynamic behavior và chưa chứng minh run xảy ra.","Static parsing|SQL/code parser rẻ và pre-run nhưng dialect, macros, UDF, dynamic identifiers và procedural logic tạo unknown edges.","Runtime instrumentation|Events/hooks thấy executed inputs/outputs và run context nhưng cần adoption, delivery và version compatibility.","Query-log inference|Warehouse history phản ánh execution thật song retention, permissions, temp objects và parser limits làm coverage không đầy đủ.","Manual curation|Chuyên gia bổ sung semantic edge nhưng freshness, scale và conflict với automated producers cần governance.","Hybrid evaluation|So methods trên signed fixture, đo precision/recall/unknown, latency và cost; merge theo producer authority, không union mù.")),
make_lesson(300,"Lesson_300-edge-provenance-extracted-inferred-manual-unknown","Edge provenance - extracted, inferred, manual, unknown","wiki.metadata.edge-provenance-confidence","Mỗi lineage edge phải mang provenance và confidence nào để người dùng phân biệt extracted, inferred, manual và unknown?",(OL,OF,DL),(OLL,OFL,DLL),a(
"Extracted edge|Đến từ explicit runtime event hoặc declared artifact; phải lưu producer, method, version, run/snapshot và locator.","Inferred edge|Parser, name match hoặc query analysis tạo hypothesis; confidence và unsupported constructs phải hiện rõ.","Manual edge|Human assertion cần author, rationale, scope, effective/review dates và conflict policy với automation.","Unknown state|Thiếu edge không đồng nghĩa no dependency; unknown là trạng thái hợp lệ khi extraction không quan sát được.","Conflict resolution|Không chọn edge mới nhất một cách mù quáng; authority, method, temporal scope và evidence quyết định current view.","Provenance tests|Fixture tạo true, false, ambiguous và stale edges; UI/API phải giữ origin, confidence và abstain khi không đủ bằng chứng.")),
)
